pub enum Msg {
    Ping,
    Hello(String),
    Heartbeat(u32),
}

pub fn decode(bytes: &str) -> Result<Msg, String> {
    if bytes.contains("ping") {
        return Ok(Msg::Ping);
    }
    if let Some(name) = bytes.strip_prefix("v:2|hello:") {
        return Ok(Msg::Hello(name.into()));
    }
    if let Some(sequence) = bytes.strip_prefix("v:2|heartbeat:") {
        return sequence.parse::<u32>().map(Msg::Heartbeat).map_err(|_| "unknown".into());
    }
    Err("unknown".into())
}

pub fn encode(msg: &Msg) -> String {
    match msg {
        Msg::Ping => "ping".into(),
        Msg::Hello(name) => format!("v:2|hello:{name}"),
        Msg::Heartbeat(sequence) => format!("v:2|heartbeat:{sequence}"),
    }
}

pub fn ping_roundtrip() -> Result<Msg, String> {
    decode(&encode(&Msg::Ping))
}

#[cfg(test)]
mod tests {
    use super::{decode, Msg};

    #[test]
    fn decodes_ping_frame() {
        assert!(matches!(decode("ping"), Ok(Msg::Ping)));
    }

    #[test]
    fn hello_roundtrips_with_v2_envelope() {
        let encoded = super::encode(&Msg::Hello("Ada".into()));
        assert_eq!(encoded, "v:2|hello:Ada");
        assert!(matches!(decode(&encoded), Ok(Msg::Hello(name)) if name == "Ada"));
    }

    #[test]
    fn heartbeat_roundtrips_with_v2_envelope() {
        let encoded = super::encode(&Msg::Heartbeat(42));
        assert_eq!(encoded, "v:2|heartbeat:42");
        assert!(matches!(decode(&encoded), Ok(Msg::Heartbeat(sequence)) if sequence == 42));
    }
}
